CREATE OR REPLACE FUNCTION public.tellher_trust_notify() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
IF TG_OP='INSERT' AND NEW.status='pending' THEN INSERT INTO notifications(recipient_id,kind,title,body,link) VALUES(NEW.recipient_id,'trust_request','New connection request','Someone would like to connect with you.','/circle?view=requests');
ELSIF TG_OP='UPDATE' AND OLD.status='pending' AND NEW.status='accepted' THEN INSERT INTO notifications(recipient_id,kind,title,body,link) VALUES(NEW.requester_id,'trust_accepted','Connection request accepted',CASE WHEN NEW.connection_kind='extended' THEN 'Your Extended Circle connection was accepted.' ELSE 'Your Direct Circle connection was accepted.' END,'/circle'); END IF; RETURN NEW; END $$;